  (uuid_generate_v4(), 'squash-blossom-turquoise-pendant-and-earring-jewelry-set-sterling-silver-western', '4611522268', 'https://www.etsy.com/listing/4611522268/squash-blossom-turquoise-pendant-and?click_key=7734c4c2-8642-4296-ad51-b4d40acfa262%3ALT7e01ebffda26409b2b17188b4ef90a665f874525&click_sum=c10e7516&ls=s&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-126846-19-3&sr_prefetch=1&pf_from=search&pro=1&frs=1&sts=1&content_source=7734c4c2-8642-4296-ad51-b4d40acfa262%253ALT7e01ebffda26409b2b17188b4ef90a665f874525',
   'Squash Blossom Turquoise Pendant and Earring Jewelry Set. Sterling Silver Western Turquoise Jewelry Set.', 'Discover timeless elegance with the handmade Turquoise & Sterling Silver Blossom set. Each piece highlights unique, natural turquoise stones. The pendant is roughly 1.5" long and will come on an 18” solid sterling silver chain, with earrings dropping about 1.7". Stones are natural and may vary. Whether it’s for yourself or a gift for someone special, your order will arrive beautifully packaged. Shipping & Returns Policy: We are pleased to offer free domestic standard shipping on all orders over $35. Due to the significant cost of providing this service, all sales with an applied free shipping discount are considered final. We are unable to accept returns or exchanges on those orders. Accelerated shipping is available for customers who need their order faster than standard delivery. For an additional cost you are able change to your preferred shipping option at checkout.', 'statement-pieces',
