  (uuid_generate_v4(), 'native-american-handmade-sterling-silver-navajo-pearl-stud-earrings-5-8-oxidized', '4576796719', 'https://www.etsy.com/listing/4576796719/native-american-handmade-sterling-silver?click_key=386bdd14-7031-41bb-872a-cd920b3f275a%3ALT4cdf16c8b18b272b0b808222a7658fa5f2d78199&click_sum=3aff1f98&ls=s&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-1072117-18-45&sr_prefetch=1&pf_from=search&frs=1&cns=1&sts=1&content_source=386bdd14-7031-41bb-872a-cd920b3f275a%253ALT4cdf16c8b18b272b0b808222a7658fa5f2d78199',
